begin;
create extension if not exists pgtap with schema extensions;
select plan(17);
select ok(not has_function_privilege('anon','public.check_b2c_package_edit()','EXECUTE'),'Package trigger not anonymous RPC');
select ok(not has_function_privilege('anon','public.check_b2c_receipt_balance()','EXECUTE'),'Receipt trigger not anonymous RPC');
insert into public.b2c_students(id,source_key,full_name) values ('46000000-0000-4000-8000-000000000001','test-b2c-tuition','TEST-TUITION');
insert into public.b2c_classes(id,program_slug,name) values ('46000000-0000-4000-8000-000000000002','tieng-anh','TEST-TUITION');
insert into public.b2c_enrollments(id,source_key,class_id,student_id) values ('46000000-0000-4000-8000-000000000003','test-b2c-tuition','46000000-0000-4000-8000-000000000002','46000000-0000-4000-8000-000000000001');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.b2c_tuition_packages'::regclass,'public.b2c_tuition_receipts'::regclass)),'RLS enabled');
select set_config('request.jwt.claims',json_build_object('sub',(select id from public.profiles where role in ('super_admin','academic_manager') and is_active limit 1),'role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$select public.save_b2c_tuition_package('46000000-0000-4000-8000-000000000003',12,100000,200000,' ')$$,'23514',null,'Discount requires reason');
select lives_ok($$select public.save_b2c_tuition_package('46000000-0000-4000-8000-000000000003',12,100000,200000,'Promotion')$$,'Create package');
select is((select total_due from public.b2c_tuition_packages where enrollment_id='46000000-0000-4000-8000-000000000003'),1000000::numeric,'Calculated total');
select lives_ok($$select public.record_b2c_tuition_receipt((select id from public.b2c_tuition_packages where enrollment_id='46000000-0000-4000-8000-000000000003'),'46000000-0000-4000-8000-000000000004','2026-10-13',400000,'cash','Collector')$$,'First installment');
select lives_ok($$select public.record_b2c_tuition_receipt((select id from public.b2c_tuition_packages where enrollment_id='46000000-0000-4000-8000-000000000003'),'46000000-0000-4000-8000-000000000004','2026-10-13',400000,'cash','Collector')$$,'Retry same request');
select is((select count(*)::integer from public.b2c_tuition_receipts where request_id='46000000-0000-4000-8000-000000000004'),1,'Retry does not duplicate payment');
select throws_ok($$select public.record_b2c_tuition_receipt((select id from public.b2c_tuition_packages where enrollment_id='46000000-0000-4000-8000-000000000003'),'46000000-0000-4000-8000-000000000004','2026-10-13',400001,'cash','Collector')$$,'22023',null,'Cannot change reused request');
select lives_ok($$select public.record_b2c_tuition_receipt((select id from public.b2c_tuition_packages where enrollment_id='46000000-0000-4000-8000-000000000003'),'46000000-0000-4000-8000-000000000005','2026-10-14',600000,'bank_transfer','Collector')$$,'Second installment');
select is((public.get_b2c_tuition_page('TEST-TUITION',0)->>'paid_amount')::numeric,1000000::numeric,'Summary includes both installments');
select throws_ok($$select public.record_b2c_tuition_receipt((select id from public.b2c_tuition_packages where enrollment_id='46000000-0000-4000-8000-000000000003'),'46000000-0000-4000-8000-000000000006','2026-10-14',1,'cash','Collector')$$,'22023',null,'Overpayment blocked');
select throws_ok($$select public.save_b2c_tuition_package('46000000-0000-4000-8000-000000000003',1,100000,0,'')$$,'22023',null,'Cannot reduce total below paid');
select throws_ok($$delete from public.b2c_tuition_receipts where request_id='46000000-0000-4000-8000-000000000004'$$,'42501',null,'Receipts cannot be deleted');
select throws_ok($$select public.record_b2c_tuition_receipt((select id from public.b2c_tuition_packages where enrollment_id='46000000-0000-4000-8000-000000000003'),'46000000-0000-4000-8000-000000000007','2026-10-14',1.5,'cash','Collector')$$,'22023',null,'Fractional VND blocked');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.get_b2c_tuition_page()$$,'42501',null,'Nonmanager blocked');
select * from finish();
rollback;
